const path = require('node:path');
const t = (name, f) => { try { console.log(name, String(f())); } catch (e) { console.log(name, 'ERR', e && e.message); } };
const heap = ['/usr', 'local', 'lib', 'x.txt'].join('/');
const grown = '/usr/local/'.repeat(3) + 'file.txt';
const num = String(1234567890123);
const envv = process.env.HOME || '/home/none';
t('lit-basename', () => path.basename('/a/b.txt'));
t('lit-long-basename', () => path.basename('/a/very/long/literal/path/name.txt'));
t('heap-basename', () => path.basename(heap));
t('grown-basename', () => path.basename(grown));
t('num-basename', () => path.basename(num));
t('env-basename', () => path.basename(envv));
t('join2-lit', () => path.join('/aaaa/bbbb', 'cccc/dddd'));
t('join2-heap', () => path.join(heap, grown));
t('join3', () => path.join('/a', 'b', 'c'));
t('dirname-heap', () => path.dirname(heap));
t('extname-heap', () => path.extname(heap));
t('resolve-heap', () => path.resolve(heap));
t('posix', () => path.posix.join('/a/b/c/d/e', 'f/g/h/i'));
t('type', () => typeof heap + typeof grown + heap.length);
const u = new URLSearchParams('a=1&b=2&a=3');
t('sp-getAll', () => u.getAll('a').join(','));
t('sp-toString', () => u.toString());
t('sp-has', () => u.has('b'));
u.append('c', 'x y');
t('sp-append', () => u.toString());
u.delete('b');
t('sp-delete', () => u.toString());
t('sp-concat', () => u.getAll('a').join(',') + u.toString() + u.has('c'));
t('sp-concat2', () => u.toString() + u.has('c'));
t('sp-concat3', () => 'x' + u.has('c'));
